#!/usr/bin/env python3
import re
import sys

VALID_METHODS = {'GET', 'POST', 'PUT', 'DELETE', 'PATCH'}
VALID_PERMISSIONS = {'ALLOW', 'DENY'}


def normalize_path(path):
    """Replace all valid path variable patterns with {var}."""
    return re.sub(r'\{[a-zA-Z0-9_-]+\}', '{var}', path)


def is_valid_role(role):
    """Check if role matches alphanumeric with optional underscores and hyphens."""
    return bool(role) and bool(re.match(r'^[a-zA-Z0-9_-]+$', role))


def split_sections(content):
    """Split content into three sections separated by empty lines."""
    lines = content.splitlines()
    # Find first empty line (end of ENDPOINTS)
    end1 = None
    for i, line in enumerate(lines):
        if line.strip() == '':
            end1 = i
            break
    if end1 is None:
        return [lines, [], []]
    # Find second empty line (end of BASE/EXCLUDE)
    end2 = None
    for i in range(end1 + 1, len(lines)):
        if lines[i].strip() == '':
            end2 = i
            break
    if end2 is None:
        return [lines[:end1], lines[end1 + 1:], []]
    return [lines[:end1], lines[end1 + 1:end2], lines[end2 + 1:]]


def parse_endpoints(lines):
    """Parse ENDPOINTS section with hard cutoff on malformed lines."""
    endpoints = []
    for line in lines:
        parts = line.split()
        if len(parts) != 4:
            break
        path, method, role, perm = parts
        if not path.strip():
            break
        method_upper = method.upper()
        if method_upper not in VALID_METHODS:
            break
        perm_upper = perm.upper()
        if perm_upper not in VALID_PERMISSIONS:
            break
        if not role.strip() or not is_valid_role(role):
            break
        endpoints.append((path, method_upper, role, perm_upper))
    return endpoints


def parse_base_exclude(lines):
    """Parse BASE/EXCLUDE section."""
    base_path = None
    excluded_roles = set()
    for line in lines:
        parts = line.split()
        if not parts:
            continue
        if parts[0] == 'base':
            if len(parts) == 2:
                base_path = parts[1]
        elif parts[0] == 'exclude':
            excluded_roles = set(parts[1:])
    return base_path, excluded_roles


def parse_plan(lines):
    """Parse PLAN section with hard cutoff on malformed lines."""
    plan = []
    for line in lines:
        parts = line.split()
        if len(parts) != 2:
            break
        path, method = parts
        if not path.strip():
            break
        method_upper = method.upper()
        if method_upper not in VALID_METHODS:
            break
        plan.append((path, method_upper))
    return plan


def main():
    with open('/app/input.txt') as f:
        content = f.read()

    sections = split_sections(content)
    endpoints = parse_endpoints(sections[0])
    base_path, excluded_roles = parse_base_exclude(sections[1])
    plan = parse_plan(sections[2])

    # Deduplicate by (normalized_path, method, role) - keep first encountered
    seen = set()
    deduped = []
    for ep in endpoints:
        key = (normalize_path(ep[0]), ep[1], ep[2])
        if key not in seen:
            seen.add(key)
            deduped.append(ep)

    # Filter by base prefix (original path, not normalized)
    if base_path is not None:
        deduped = [ep for ep in deduped if ep[0].startswith(base_path)]

    if not plan:
        # PLAN is empty: include all eligible, filter out excluded roles
        result = [ep for ep in deduped if ep[2] not in excluded_roles]
    else:
        result_indices = set()

        # Find PLAN entries that match ENDPOINTS
        plan_matched_paths = set()
        for pp, pm in plan:
            pp_norm = normalize_path(pp)
            found = False
            for i, ep in enumerate(deduped):
                if normalize_path(ep[0]) == pp_norm and ep[1] == pm:
                    found = True
                    if ep[2] not in excluded_roles:
                        result_indices.add(i)
            if found:
                plan_matched_paths.add(pp_norm)

        # Parent path resolution
        for pp_norm in plan_matched_paths:
            for ep in deduped:
                ep_norm = normalize_path(ep[0])
                if ep_norm != pp_norm and pp_norm.startswith(ep_norm):
                    # Candidate parent path - collect all endpoints for this path
                    parent_eps = [(i, e) for i, e in enumerate(deduped) if normalize_path(e[0]) == ep_norm]
                    if not parent_eps:
                        continue
                    has_non_excluded = any(e[2] not in excluded_roles for _, e in parent_eps)
                    all_excluded = all(e[2] in excluded_roles for _, e in parent_eps)
                    if has_non_excluded:
                        for i, e in parent_eps:
                            if e[2] not in excluded_roles:
                                result_indices.add(i)
                    elif all_excluded:
                        # Special case: include excluded endpoints if parent is needed
                        for i, e in parent_eps:
                            result_indices.add(i)

        result = [deduped[i] for i in sorted(result_indices)]

    # Sort by specificity
    def sort_key(ep):
        path, method, role, perm = ep
        segments = [s for s in path.split('/') if s]
        return (-len(segments), method, role, 0 if perm == 'ALLOW' else 1)

    result.sort(key=sort_key)

    # Output
    with open('/app/output.txt', 'w') as f:
        if not result:
            f.write('\n')
        else:
            for ep in result:
                f.write(f'{ep[0]} {ep[1]} {ep[2]} {ep[3]}\n')


if __name__ == '__main__':
    main()
